// ฟังก์ชันดึงการจับคู่ชื่อปัจจุบัน
window.getNameMapping = function() {
  try {
    const saved = localStorage.getItem('crh_staff_name_map');
    if (saved) return JSON.parse(saved);
  } catch (e) {}
  return Object.assign({}, window.DEFAULT_NAME_MAPPING);
};

// ฟังก์ชันดึงข้อมูลชื่อของบุคลากร (รองรับทั้งชื่อเล่นและชื่อจริง)
window.getResolvedStaff = function(identifier) {
  const userMap = window.getNameMapping();
  
  // ถ้าตัวระบุเป็นชื่อเล่น
  if (window.NICKNAME_LIST.includes(identifier)) {
    const real = userMap[identifier] || '';
    return {
      nickname: identifier,
      realName: real,
      displayName: real ? `คุณ${real} (${identifier})` : `คุณ${identifier}`,
      shortName: identifier,
      isPaired: !!real
    };
  }
  
  // ถ้าตัวระบุเป็นชื่อจริง
  let matchedNick = '';
  for (let n in userMap) {
    if (userMap[n] === identifier) {
      matchedNick = n;
      break;
    }
  }
  return {
    nickname: matchedNick,
    realName: identifier,
    displayName: matchedNick ? `คุณ${identifier} (${matchedNick})` : `คุณ${identifier}`,
    shortName: matchedNick || identifier.split(' ')[0],
    isPaired: !!matchedNick
  };
};

// ฟังก์ชันคำนวณการแทนเวร "แทน บ่ายดึก" เชื่อมโยงระหว่างคนที่มีเวร IPD ดึก/บ่าย กับคนที่ขึ้นแทน
window.getSubstitutionInfo = function(date, viewingNickname, viewingRealName) {
  const dayStations = window.ALL_DAILY_STATIONS[date];
  if (!dayStations) return null;

  // 1. หาว่าใครในตารางเวลาปกติมีหน้าที่ "แทน บ่ายดึก" ในวันนี้
  let substituteNickname = null;
  for (let nick in dayStations) {
    if (dayStations[nick].includes("แทน บ่ายดึก")) {
      substituteNickname = nick;
      break;
    }
  }

  // 2. หาว่าใครมีเวร IPD ดึก หรือ IPD บ่าย ในวันนี้จากไฟล์ Excel
  let nightShiftRealName = null;
  let nightShiftDuties = [];
  if (window.ALL_STAFF_OT) {
    for (let realName in window.ALL_STAFF_OT) {
      const otList = window.ALL_STAFF_OT[realName]["" + date] || [];
      const ipdDuties = otList.filter(ot => ot.type === "IPD" && (ot.name.includes("ดึก") || ot.name.includes("บ่าย")));
      if (ipdDuties.length > 0) {
        nightShiftRealName = realName;
        nightShiftDuties = ipdDuties;
        break;
      }
    }
  }

  if (!nightShiftRealName && !substituteNickname) return null;

  // 3. แปลงชื่อจริงของคนอยู่เวรดึก/บ่าย ให้เป็นชื่อเล่น
  const userMap = window.getNameMapping();
  let nightShiftNickname = null;
  for (let nick in userMap) {
    if (userMap[nick] === nightShiftRealName) {
      nightShiftNickname = nick;
      break;
    }
  }

  // 4. ค้นหาจุดเข้างานปกติของคนที่อยู่เวรดึก/บ่าย (จุดที่คนแทนบ่ายดึกต้องไปเข้าแทน)
  let targetStation = null;
  let targetLocation = null;
  if (nightShiftNickname && dayStations[nightShiftNickname]) {
    targetStation = dayStations[nightShiftNickname];
    targetLocation = getStationLocation(targetStation);
  }

  // 5. ตรวจสอบบทบาทของคนที่กำลังเปิดดูอยู่ (viewingNickname หรือ viewingRealName)
  const norm = str => (str || '').replace(/\s+/g, ' ').trim().toLowerCase();
  const vNick = norm(viewingNickname);
  const vReal = norm(viewingRealName);
  const sNick = norm(substituteNickname);
  const nReal = norm(nightShiftRealName);
  const nNick = norm(nightShiftNickname);

  const isViewerSubstitute = (
    (vNick && (vNick === sNick || (userMap[vNick] && norm(userMap[vNick]) === sNick))) ||
    (vReal && userMap[substituteNickname] && norm(userMap[substituteNickname]) === vReal)
  );
  const isViewerNightShift = (
    (vNick && (vNick === nNick || (userMap[vNick] && norm(userMap[vNick]) === nReal))) ||
    (vReal && (vReal === nReal || (nightShiftNickname && norm(userMap[nightShiftNickname]) === vReal)))
  );

  return {
    date: date,
    substituteNickname: substituteNickname,
    nightShiftRealName: nightShiftRealName,
    nightShiftNickname: nightShiftNickname,
    targetStation: targetStation,
    targetLocation: targetLocation,
    nightShiftDuties: nightShiftDuties,
    isViewerSubstitute: isViewerSubstitute,
    isViewerNightShift: isViewerNightShift
  };
};

// ฟังก์ชันสร้างตารางของบุคคลที่เลือก (ไม่ล็อกที่เอ็ม)
window.buildMonthSchedule = function(selectedIdentifier) {
  const daysOfWeek = ["อาทิตย์", "จันทร์", "อังคาร", "พุธ", "พฤหัส", "ศุกร์", "เสาร์"];
  const customNotes = JSON.parse(localStorage.getItem('crh_custom_day_notes') || '{}');
  const staff = window.getResolvedStaff(selectedIdentifier);

  const nickname = staff.nickname;
  const realName = staff.realName;

  const list = [];
  const staffOtData = (realName && window.ALL_STAFF_OT[realName]) ? window.ALL_STAFF_OT[realName] : {};

  for (let date = 1; date <= 30; date++) {
    const dayOfWeekIndex = (date - 1) % 7;
    const dayName = daysOfWeek[dayOfWeekIndex];
    const isWeekend = (dayOfWeekIndex === 0 || dayOfWeekIndex === 6);

    // หางานประจำวัน (เวลาปกติ) จากชื่อเล่น
    let regularDuty = null;
    const dayStations = window.ALL_DAILY_STATIONS[date];
    if (!isWeekend && dayStations && nickname) {
      for (let nick in dayStations) {
        if (nick === nickname || (nick === "แตงกวา" && nickname === "แตง")) {
          const pointName = dayStations[nick];
          regularDuty = {
            title: pointName,
            location: getStationLocation(pointName)
          };
          break;
        }
      }
    }

    // เวรนอกเวลา / OT จากชื่อจริงใน Excel
    const otList = staffOtData["" + date] || [];
    const hasDuty = otList.length > 0;
    const isDayOff = (!regularDuty && !hasDuty);
    const userNote = customNotes[date] || null;

    // ข้อมูลเชื่อมโยงเวรแทนบ่ายดึก
    const subInfo = window.getSubstitutionInfo(date, nickname, realName);

    list.push({
      date: date,
      dayName: dayName,
      dayOfWeekIndex: dayOfWeekIndex,
      isWeekend: isWeekend,
      regularDuty: regularDuty,
      otDuties: otList,
      hasDuty: hasDuty,
      isDayOff: isDayOff,
      userNote: userNote,
      substitutionInfo: subInfo
    });
  }

  return list;
};

// สรุปสถิติของบุคคลที่เลือก
window.getStationStats = function(selectedIdentifier) {
  const schedule = window.buildMonthSchedule(selectedIdentifier);
  const stationCounts = {};
  let totalWorkDays = 0;
  let totalOtShifts = 0;
  let totalOffDays = 0;

  schedule.forEach(day => {
    if (day.regularDuty) {
      const p = day.regularDuty.title;
      stationCounts[p] = (stationCounts[p] || 0) + 1;
      totalWorkDays++;
    }
    if (day.otDuties && day.otDuties.length > 0) {
      totalOtShifts += day.otDuties.length;
    }
    if (day.isDayOff) {
      totalOffDays++;
    }
  });

  return {
    stationCounts: stationCounts,
    totalWorkDays: totalWorkDays,
    totalOtShifts: totalOtShifts,
    totalOffDays: totalOffDays
  };
};

function getStationLocation(pointName) {
  if (!pointName) return "กลุ่มงานการเงิน";
  if (pointName.includes("PCU")) return "ตึกบริการปฐมภูมิ (PCU)";
  if (pointName.includes("ER")) return "ห้องอุบัติเหตุและฉุกเฉิน (ER)";
  if (pointName.includes("ตึกรังสี")) return "อาคารรังสีวินิจฉัย";
  if (pointName.includes("เซ็นทรัล")) return "จุดเก็บเงินเซ็นทรัล / ศูนย์การแพทย์";
  if (pointName.includes("OPD ชั้น 2")) return "อาคารผู้ป่วยนอก (OPD) ชั้น 2";
  if (pointName.includes("OPD ชั้น 3")) return "อาคารผู้ป่วยนอก (OPD) ชั้น 3";
  if (pointName.includes("NO.9")) return "ห้องเบอร์ 9 อาคารผู้ป่วยนอก";
  if (pointName.includes("เก็บเงิน 19")) return "จุดเก็บเงิน เบอร์ 19";
  if (pointName.includes("คิดชาร์ท 19")) return "จุดคิดชาร์ท เบอร์ 19";
  if (pointName.includes("เก็บเงิน 999")) return "จุดเก็บเงิน เบอร์ 999";
  if (pointName.includes("คิดชาร์ท 999")) return "จุดคิดชาร์ท เบอร์ 999";
  if (pointName.includes("เก็บเงิน 119")) return "จุดเก็บเงิน เบอร์ 119";
  if (pointName.includes("แทน บ่ายดึก")) return "จุดหมุนเวียนเวรแทน บ่าย-ดึก";
  return pointName;
}
